    adcs_vec3_t axis_n;
    adcs_vec3_t h_next;
    double omega_unclamped;
    double omega_next;
    double norm_axis;

    if ((wheel == NULL) || (next_wheel == NULL) || (next_momentum == NULL) || (saturated == NULL)) {
        return ADCS_E_NULL;
    }

    if ((!adcs_is_finite_vec3(&wheel->axis_body)) ||
        (!isfinite(wheel->inertia_kg_m2)) ||
        (!isfinite(wheel->speed_rad_s)) ||
        (!isfinite(motor_torque)) ||
        (!isfinite(dt)) ||
        (!isfinite(speed_limit)) ||
        (wheel->inertia_kg_m2 <= 0.0) ||
        (dt < 0.0) ||
        (speed_limit <= 0.0)) {
        return ADCS_E_RANGE;
    }

    norm_axis = adcs_vec3_norm(&wheel->axis_body);
    if (norm_axis <= ADCS_EPS_NORM) {
        return ADCS_E_RANGE;
    }

    axis_n = adcs_vec3_scale(&wheel->axis_body, 1.0 / norm_axis);

    omega_unclamped = wheel->speed_rad_s + motor_torque * dt / wheel->inertia_kg_m2;
    omega_next = ADCS_CLAMP(omega_unclamped, -speed_limit, speed_limit);

    if (fabs(omega_unclamped) > speed_limit) {
        *saturated = 1;
    } else {
        *saturated = 0;
    }

    next_wheel->axis_body = axis_n;
    next_wheel->inertia_kg_m2 = wheel->inertia_kg_m2;
    next_wheel->speed_rad_s = omega_next;

    h_next = adcs_vec3_scale(&axis_n, wheel->inertia_kg_m2 * omega_next);
    *next_momentum = h_next;

    return ADCS_OK;
}

